import {t,ui,onLanguageChange} from './i18n.js';
const escape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
export function createQuickActions({onAction}){
  const host=document.createElement('section');host.className='quick-actions';host.setAttribute('aria-label',t('Azioni rapide'));document.querySelector('.page-heading').after(host);
  const dialog=document.createElement('dialog');dialog.className='quick-dialog';dialog.id='quick-actions-dialog';dialog.setAttribute('aria-labelledby','quick-title');document.body.append(dialog);
  const actions=[['today','Oggi'],['memory-review','Rivedi memoria'],['search','Cerca nello studio'],['task','Nuovo incarico'],['memory','Nuova memoria'],['review','Da revisionare'],['workflows','Vai alle procedure'],['github','Vai ai test GitHub'],['repositories','Vai ai repository']];
  let scopeName='',count=0,blocked=false,returnFocus=null;
  function run(id){if(blocked&&['task','memory'].includes(id))return;dialog.close();onAction(id);}
  function render(){host.innerHTML=ui`<span class="quick-context">${escape(scopeName)}</span><div class="quick-buttons"><button type="button" data-quick-action="today">Oggi</button><button type="button" data-quick-action="search">⌕ Cerca nello studio</button><button type="button" data-quick-action="task">＋ Nuovo incarico</button><button type="button" data-quick-action="memory">＋ Nuova memoria</button><button type="button" data-quick-action="review"><span>Da revisionare</span><span class="quick-count">${count}</span></button><button type="button" data-quick-open aria-label="Apri azioni rapide">⌘ / Ctrl K <span aria-hidden="true">⌕</span></button></div>`;host.setAttribute('aria-label',t('Azioni rapide'));locks();}
  function locks(){host.querySelectorAll('[data-quick-action="task"],[data-quick-action="memory"]').forEach(button=>button.disabled=blocked);}
  function list(){const value=dialog.querySelector('input').value.trim().toLocaleLowerCase();dialog.querySelector('.quick-list').innerHTML=actions.filter(([,label])=>t(label).toLocaleLowerCase().includes(value)).map(([id,label])=>ui`<button type="button" data-quick-action="${id}"${blocked&&['task','memory'].includes(id)?' disabled':''}><span>${escape(t(label))}</span><span aria-hidden="true">↗</span></button>`).join('')||ui`<p>Nessuna azione corrisponde.</p>`;}
  function open(){if(document.querySelector('dialog[open]'))return;returnFocus=document.activeElement;renderDialog();dialog.showModal();dialog.querySelector('input').focus();}
  function renderDialog(){const value=dialog.querySelector('input')?.value||'';dialog.innerHTML=ui`<div class="quick-dialog-heading"><h2 id="quick-title">Azioni rapide</h2><button type="button" data-quick-close aria-label="Chiudi finestra">✕</button></div><input id="quick-action-search" type="search" placeholder="Cerca un’azione…" aria-label="Cerca un’azione…" autocomplete="off"><div class="quick-list"></div><p class="quick-hint">Tutte le azioni preparano o aprono il lavoro. Le chiamate AI richiedono un avvio esplicito.</p>`;dialog.querySelector('input').value=value;dialog.querySelector('input').addEventListener('input',list);list();}
  host.addEventListener('click',event=>{const button=event.target.closest('button');if(!button||button.disabled)return;if(button.hasAttribute('data-quick-open'))open();else run(button.dataset.quickAction);});
  dialog.addEventListener('click',event=>{const button=event.target.closest('button');if(!button||button.disabled)return;if(button.hasAttribute('data-quick-close'))dialog.close();else run(button.dataset.quickAction);});
  dialog.addEventListener('keydown',event=>{const buttons=[...dialog.querySelectorAll('.quick-list button:not([disabled])')];if(!buttons.length)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const index=buttons.indexOf(document.activeElement),next=event.key==='ArrowDown'?(index+1)%buttons.length:(index<0?buttons.length-1:(index-1+buttons.length)%buttons.length);buttons[next].focus();}if(event.key==='Enter'&&event.target.matches('input')){event.preventDefault();buttons[0].click();}});
  dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))returnFocus?.focus({preventScroll:true});});
  document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'&&!event.altKey&&!event.isComposing&&!document.querySelector('dialog[open]')){event.preventDefault();open();}});
  onLanguageChange(()=>{render();if(dialog.open)renderDialog();});render();
  return {setContext(value){scopeName=value.scopeName||'';count=value.reviewCount||0;blocked=Boolean(value.busy);host.querySelector('.quick-context').textContent=scopeName;host.querySelector('.quick-count').textContent=count;locks();},open};
}
